#include <string>
#include <vector>

class Solution {
public:
    long long countOfSubstrings(std::string word, int k) {
        auto is_vowel = [](char c) {
            return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
        };

        auto at_least = [&](int target_k) {
            int cnt_v[26] = {0};
            int vowel_kinds = 0;
            int consonants = 0;
            int left = 0;
            long long res = 0;
            int n = word.size();

            for (int right = 0; right < n; ++right) {
                char ch = word[right];
                if (is_vowel(ch)) {
                    if (cnt_v[ch - 'a'] == 0) vowel_kinds++;
                    cnt_v[ch - 'a']++;
                } else {
                    consonants++;
                }

                while (vowel_kinds == 5 && consonants >= target_k) {
                    res += n - right;
                    char l_ch = word[left];
                    if (is_vowel(l_ch)) {
                        cnt_v[l_ch - 'a']--;
                        if (cnt_v[l_ch - 'a'] == 0) vowel_kinds--;
                    } else {
                        consonants--;
                    }
                    left++;
                }
            }
            return res;
        };

        return at_least(k) - at_least(k + 1);
    }
};

class Solution {
    public long countOfSubstrings(String word, int k) {
        return atLeast(word, k) - atLeast(word, k + 1);
    }

    private boolean isVowel(char c) {
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }

    private long atLeast(String word, int targetK) {
        int[] cntV = new int[26];
        int vowelKinds = 0;
        int consonants = 0;
        int left = 0;
        long res = 0;
        int n = word.length();

        for (int right = 0; right < n; right++) {
            char ch = word.charAt(right);
            if (isVowel(ch)) {
                if (cntV[ch - 'a'] == 0) vowelKinds++;
                cntV[ch - 'a']++;
            } else {
                consonants++;
            }

            while (vowelKinds == 5 && consonants >= targetK) {
                res += n - right;
                char lCh = word.charAt(left);
                if (isVowel(lCh)) {
                    cntV[lCh - 'a']--;
                    if (cntV[lCh - 'a'] == 0) vowelKinds--;
                } else {
                    consonants--;
                }
                left++;
            }
        }
        return res;
    }
}

var countOfSubstrings = function(word, k) {
    function isVowel(c) {
        return c === 'a' || c === 'e' || c === 'i' || c === 'o' || c === 'u';
    }

    function atLeast(targetK) {
        const cntV = new Int32Array(26);
        let vowelKinds = 0;
        let consonants = 0;
        let left = 0;
        let res = 0;
        const n = word.length;

        for (let right = 0; right < n; right++) {
            const ch = word[right];
            const idx = word.charCodeAt(right) - 97;
            if (isVowel(ch)) {
                if (cntV[idx] === 0) vowelKinds++;
                cntV[idx]++;
            } else {
                consonants++;
            }

            while (vowelKinds === 5 && consonants >= targetK) {
                res += n - right;
                const lCh = word[left];
                const lIdx = word.charCodeAt(left) - 97;
                if (isVowel(lCh)) {
                    cntV[lIdx]--;
                    if (cntV[lIdx] === 0) vowelKinds--;
                } else {
                    consonants--;
                }
                left++;
            }
        }
        return res;
    }

    return atLeast(k) - atLeast(k + 1);
};
